using System.IO.MemoryMappedFiles;
using System.Text.Json;
using NAudio.CoreAudioApi;
using NAudio.Wave;
namespace OpenEQ;
internal static class NativeApoChecks {
 public static int Run(string path,string name,bool listen=false,bool multiple=false){var report=new Dictionary<string,object>();WindowsListen.ListenInfo? original=null;NativeApo? apo=null;var children=new List<System.Diagnostics.Process>();WasapiCapture? mic=null;long captureBytes=0;double micPeak=0;
  try{var device=AudioEngine.Devices().Single(d=>d.Name.Contains(name,StringComparison.OrdinalIgnoreCase));report["device"]=device;if(!NativeApo.Installed(device.Id))throw new Exception("Native APO not installed on this endpoint");
   // Installation already refreshes the audio host; avoid hiding an active endpoint.
   
   var preset=Preset.Flat();preset.Bands.Clear();preset.Output.Protection=false;preset.Bands.Add(new Band{Frequency=1000,Gain=-12.1,Q=2,Channel="left"});apo=new NativeApo(device.Id,preset,false);using var enumerator=new MMDeviceEnumerator();using var physical=enumerator.GetDevice(device.Id);var mix=physical.AudioClient.MixFormat;report["mix_format"]=mix.ToString();
   using var tone=multiple?null:new WasapiOut(physical,AudioClientShareMode.Shared,true,60);if(tone!=null){tone.Init(new FloatProvider(new StereoTone(mix.SampleRate),mix));tone.Play();}else{for(int channel=0;channel<2;channel++){var start=new System.Diagnostics.ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,CreateNoWindow=true};if(string.Equals(Path.GetFileNameWithoutExtension(Environment.ProcessPath),"dotnet",StringComparison.OrdinalIgnoreCase))start.ArgumentList.Add(Path.Combine(AppContext.BaseDirectory,"OpenDSP.dll"));foreach(string arg in new[]{"--apo-tone",device.Id,channel.ToString(),"10"})start.ArgumentList.Add(arg);children.Add(System.Diagnostics.Process.Start(start)??throw new Exception("Could not start independent native tone application"));}report["independent_application_processes"]=children.Select(p=>p.Id).ToArray();}Thread.Sleep(1200);
   if(apo.Frames==0||apo.AudioProcessId==0||apo.AudioProcessId==Environment.ProcessId)throw new Exception("No external Windows audio process has executed the native APO");
   using var stream=new FileStream(NativeApo.ConfigPath(device.Id),FileMode.Open,FileAccess.ReadWrite,FileShare.ReadWrite);using var map=MemoryMappedFile.CreateFromFile(stream,null,4096,MemoryMappedFileAccess.ReadWrite,HandleInheritability.None,true);using var view=map.CreateViewAccessor();
   double[] Snapshot()=>new[]{view.ReadDouble(1456),view.ReadDouble(1464),view.ReadDouble(1472),view.ReadDouble(1480)};
   double[]? warm=null;var sw=System.Diagnostics.Stopwatch.StartNew();while(sw.ElapsedMilliseconds<10000){var s=Snapshot();if(warm!=null&&s[0]>warm[0])break;warm=s;Thread.Sleep(200);}double[] before=Snapshot();long frames=apo.Frames;Thread.Sleep(1500);double[] after=Snapshot();double inL=after[0]-before[0],inR=after[1]-before[1];if(inL<=0||inR<=0)throw new Exception("澶栭儴闊虫簮鏈帹杩涜緭鍏ヨ鏁板櫒锛堝喎鍚姩瓒呮椂锛塱nL="+inL+" inR="+inR);double left=10*Math.Log10((after[2]-before[2])/inL),right=10*Math.Log10((after[3]-before[3])/inR);if(!double.IsFinite(left)||Math.Abs(left+12.1)>.08||!double.IsFinite(right)||Math.Abs(right)>.02)throw new Exception($"Native AudioDG EQ response mismatch L={left} R={right}");
   report["left_db"]=left;report["right_db"]=right;report["health"]=apo.Health();report["frame_delta"]=apo.Frames-frames;report["audio_process"]=System.Diagnostics.Process.GetProcessById((int)apo.AudioProcessId).ProcessName;report["path"]="Windows physical endpoint → native OpenEQ APO → hardware; no OpenEQ capture/resampler";
   preset.Bands[0].Gain=-6.1;apo.Update(preset);Thread.Sleep(500);before=Snapshot();Thread.Sleep(1100);after=Snapshot();double updated=10*Math.Log10((after[2]-before[2])/(after[0]-before[0]));if(Math.Abs(updated+6.1)>.08)throw new Exception("Native live 0.1 dB update failed: "+updated);report["updated_left_db"]=updated;tone?.Stop();
   if(listen){original=WindowsListen.ReadAll().Single(x=>x.Name.Contains(name,StringComparison.OrdinalIgnoreCase));report["listen_before"]=original;WindowsListen.SetEnabled(original.Id,false);WindowsListen.RestoreSettings(original with{Enabled=false,Target=device.Id,TargetType=31});WindowsListen.SetEnabled(original.Id,true);Thread.Sleep(700);using var captureDevice=enumerator.GetDevice(original.Id);mic=new WasapiCapture(captureDevice);mic.DataAvailable+=(s,e)=>{Interlocked.Add(ref captureBytes,e.BytesRecorded);if(mic.WaveFormat.BitsPerSample==32)for(int n=0;n+3<e.BytesRecorded;n+=4)micPeak=Math.Max(micPeak,Math.Abs(BitConverter.ToSingle(e.Buffer,n)));};mic.StartRecording();long oldFrames=apo.Frames;before=Snapshot();Thread.Sleep(4000);after=Snapshot();mic.StopRecording();var during=WindowsListen.ReadAll().Single(x=>x.Id==original.Id);report["listen_during"]=during;report["microphone_bytes"]=captureBytes;report["microphone_peak"]=micPeak;report["listen_apo_input_energy_delta"]=(after[0]+after[1])-(before[0]+before[1]);if(!during.Enabled||during.Target!=device.Id||captureBytes==0||micPeak<=1e-7||apo.Frames<=oldFrames||(after[0]+after[1])<=(before[0]+before[1]))throw new Exception("Native physical Windows microphone monitoring not confirmed");report["native_windows_listen"]="PASS";}
   report["result"]="PASS";return 0;
  }catch(Exception e){report["result"]="FAIL";report["exception"]=e.ToString();return 1;}finally{foreach(var child in children){try{if(!child.HasExited){child.Kill();child.WaitForExit();}}finally{child.Dispose();}}mic?.Dispose();if(original!=null){WindowsListen.SetEnabled(original.Id,false);WindowsListen.RestoreSettings(original);report["listen_after"]=WindowsListen.ReadAll().Single(x=>x.Id==original.Id);}apo?.Dispose();report["scope"]="Native DSP executed by Windows audio host, sample rate, per-channel transfer and live update. Acoustic output requires listening or analog measurement.";File.WriteAllText(path,JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true,Encoder=System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping}));}
 }
 public static int PlayTone(string id,int channel,int seconds){using var en=new MMDeviceEnumerator();using var device=en.GetDevice(id);var mix=device.AudioClient.MixFormat;using var output=new WasapiOut(device,AudioClientShareMode.Shared,true,60);output.Init(new FloatProvider(new StereoTone(mix.SampleRate,channel),mix));output.Play();Thread.Sleep(seconds*1000);output.Stop();return 0;}
 sealed class StereoTone:NAudio.Wave.ISampleProvider {long frame;readonly int rate,channel;public WaveFormat WaveFormat{get;}public StereoTone(int rate,int channel=-1){this.rate=rate;this.channel=channel;WaveFormat=WaveFormat.CreateIeeeFloatWaveFormat(rate,2);}public int Read(float[] b,int offset,int count){for(int n=offset;n+1<offset+count;n+=2){b[n]=channel==1?0:float.CreateChecked(.003*Math.Sin(2*Math.PI*1000*frame/rate));b[n+1]=channel==0?0:float.CreateChecked(.003*Math.Sin(2*Math.PI*3000*frame/rate));frame++;}return count;}}
}

